@dataclass
class Node:
    tag: str
    attrs: dict[str, str] = field(default_factory=dict)
    children: list = field(default_factory=list)
    parent: Node | None = None

    def has_class(self, name):
        return name in self.attrs.get('class', '').split()

    def walk(self):
        yield self
        for child in self.children:
            if isinstance(child, Node):
                yield from child.walk()

    def find_class(self, name):
        return next((n for n in self.walk() if n.has_class(name)), None)

    def text(self):
        return ''.join(c.text() if isinstance(c, Node) else c for c in self.children)


class DOMParser(HTMLParser):
    VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
            'link', 'meta', 'param', 'source', 'track', 'wbr'}

    def __init__(self, html):
        super().__init__(convert_charrefs=True)
        self.root = Node('document')
        self.stack = [self.root]
        self.feed(html)
        self.close()

    def handle_starttag(self, tag, attrs):
        # HTMLParser is a tokenizer: implement the common optional li/p end tags.
        if tag == 'li' and self.stack[-1].tag == 'li':
            self.stack.pop()
        if tag == 'p' and self.stack[-1].tag == 'p':
            self.stack.pop()
        node = Node(tag, dict((k, v or '') for k, v in attrs), parent=self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in self.VOID:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in self.VOID:
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def decode_text(part):
    data = part.get_payload(decode=True) or b''
    meta = re.search(rb'charset\s*=\s*["\']?([\w-]+)', data[:8192], re.I)
    encodings = [part.get_content_charset(), meta.group(1).decode() if meta else None,
                 'utf-8-sig', 'gb18030']
    for encoding in encodings:
        if encoding:
            try:
                return data.decode(encoding)
            except (UnicodeError, LookupError):
                continue
    raise ValueError('无法识别页面字符编码，已停止导出，避免生成乱码。')


def url_key(url):
    # CID is case sensitive; URL fragments do not identify a different resource.
    return unquote(urldefrag(url.strip())[0])


class Archive:
    def __init__(self, source):
        message = BytesParser(policy=policy.default).parsebytes(source.read_bytes())
        if not message.is_multipart():
            raise ValueError(f'{source.name} 不是有效的 MHTML 多部件文件。')
        self.parts = [p for p in message.walk() if not p.is_multipart()]
        self.resources = {}
        for part in self.parts:
            location = str(part.get('Content-Location', ''))
            cid = str(part.get('Content-ID', '')).strip('<>')
            if location:
                self.resources.setdefault(url_key(location), part)
            if cid:
                self.resources['cid:' + cid] = part

    def resolve(self, url, base=''):
        return self.resources.get(url_key(url)) or self.resources.get(url_key(urljoin(base, url)))


def data_uri(uri):
    head, payload = uri.split(',', 1)
    mime = head[5:].split(';')[0] or 'application/octet-stream'
    raw = unquote_to_bytes(payload)
    return mime, base64.b64decode(raw) if ';base64' in head.lower() else raw


def page_font(root, archive, base):
    """Read the embedded font for rendering this frame, without decoding it."""
    styles = [n.text() for n in root.walk() if n.tag == 'style']
    expects_font = False
    for n in root.walk():
        if n.tag == 'link' and 'stylesheet' in n.attrs.get('rel', '').split():
            expects_font = expects_font or 'work-css-tpl' in n.attrs.get('href', '')
            part = archive.resolve(n.attrs.get('href', ''), base)
            if part is not None:
                styles.append(decode_text(part))
    selected = None
    for css in styles:
        for rule in re.findall(r'@font-face\s*\{([^}]+)\}', css, re.I):
            if 'font-cxsecret' not in rule:
                continue
            match = re.search(r'url\(\s*["\']?([^"\')]+)', rule, re.I)
            if not match:
                continue
            src = match.group(1).strip()
            if src.startswith('data:'):
                _, blob = data_uri(src)
            else:
                part = archive.resolve(src, base)
                if part is None:
                    raise ValueError('页面使用了加密字体，但字体未保存在 MHTML 中。')
                blob = part.get_payload(decode=True)
            with TTFont(io.BytesIO(blob)) as font:
                font.getBestCmap()
            selected = blob
    if expects_font and selected is None:
        raise ValueError('页面引用了加密字体样式，但归档中缺少字体资源。请重新保存已加载完成的页面。')
    return selected


def clean(text):
    text = text.replace('\xa0', ' ').replace('\u200b', '')
    text = re.sub(r'[\t\r\f\v ]+', ' ', text)
    text = re.sub(r' *\n *', '\n', text)
    return re.sub(r'\n{3,}', '\n\n', text).strip()


def md_escape(text):
    return re.sub(r'([\\`*\[\]<>])', r'\\\1', text)


class Renderer:
    EXTENSIONS = {'image/jpeg': '.jpg', 'image/jpg': '.jpg', 'image/png': '.png', 'image/gif': '.gif',
                  'image/webp': '.webp', 'image/svg+xml': '.svg', 'image/bmp': '.bmp',
                  'image/avif': '.avif', 'image/x-icon': '.ico'}
    BLOCKS = {'p', 'div', 'section', 'blockquote', 'h1', 'h2', 'h3', 'h4'}

    def __init__(self, archive, output):
        self.archive = archive
        self.output = output
        self.images = {}
        self.warnings = []
        self.context = ''

    def image(self, node, base):
        sources = [node.attrs.get(k, '') for k in ('src', 'data-original', 'data-src')]
        mime = blob = None
        for src in filter(None, sources):
            if src.startswith('data:'):
                mime, blob = data_uri(src)
            else:
                part = self.archive.resolve(src, base)
                if part is not None:
                    mime, blob = part.get_content_type(), part.get_payload(decode=True)
            if blob:
                break
        formula = ''
        if node.has_class('ans-formula-moudle'):
            try:
                formula = json.loads(unquote(node.attrs.get('data', '{}'))).get('formula', '')
            except (ValueError, TypeError):
                pass
        if not blob:
            warning = f'{self.context}：图片未保存在归档中' + (f'（公式 {formula}）' if formula else '')
            self.warnings.append(warning)
            return f' ${formula}$ ' if formula else ' **[图片缺失，需补充原图]** '
        if mime not in self.EXTENSIONS:
            raise ValueError(f'题目图片资源格式不支持：{mime}')
        digest = hashlib.sha256(blob).hexdigest()
        if digest not in self.images:
            name = digest[:20] + self.EXTENSIONS[mime]
            target = self.output / 'images' / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(blob)
            self.images[digest] = 'images/' + name
        alt = formula or node.attrs.get('alt') or '题图'
        return f'![{md_escape(alt)}]({self.images[digest]})'

    def render(self, node, base):
        if node.tag in {'script', 'style', 'input', 'button', 'select', 'template'}:
            return ''
        if node.has_class('newZy_TItle'):
            return ''
        if node.tag == 'img':
            return self.image(node, base)
        if node.tag == 'br':
            return '\n'
        items = []
        for child in node.children:
            if isinstance(child, Node):
                items.append(self.render(child, base))
            else:
                items.append(md_escape(child))
        content = ''.join(items)
        # Editors often split a continuous bold sentence into adjacent <strong>
        # spans; joining their closing/opening markers avoids literal **** text.
        content = re.sub(r'(?<!\\)\*\*(\s*)\*\*', r'\1', content)
        if node.tag in {'sub', 'sup'}:
            return f'<{node.tag}>{content}</{node.tag}>'
        if node.tag in {'strong', 'b'}:
            return '**' + content + '**'
        if node.tag in self.BLOCKS or node.tag in {'li', 'tr'}:
            return '\n\n' + content + '\n\n'
        if node.tag in {'td', 'th'}:
            return content + ' | '
        return content

    def ocr_pieces(self, node, base, prefix, encrypted=False):
        pieces, runs = [], []

        def flush():
            if runs and ''.join(text for text, _ in runs).strip():
                original = ''.join(md_escape(text) for text, _ in runs)
                pieces.append({'runs': list(runs), 'original': original,
                               'encrypted': any(flag for _, flag in runs), 'prefix': prefix})
            runs.clear()

        def visit(item, secret):
            secret = secret or item.has_class('font-cxsecret')
            if item.tag in {'script', 'style', 'input', 'button', 'select', 'template'} or item.has_class('newZy_TItle'):
                return
            if item.tag == 'img':
                flush()
                markdown = self.image(item, base)
                match = re.search(r'\]\((images/[^)]+)\)', markdown)
                piece = {'markdown': markdown}
                if match:
                    piece['image_path'] = self.output / match.group(1)
                pieces.append(piece)
                return
            if item.tag in {'sub', 'sup'}:
                runs.append((item.text(), False))
                return
            if item.tag == 'br':
                runs.append(('\n', False))
                return
            for child in item.children:
                if isinstance(child, Node):
                    visit(child, secret)
                else:
                    for part in re.split(r'(_{2,}|\$\$?[\s\S]*?\$\$?)', child):
                        if re.fullmatch(r'_{2,}|\$\$?[\s\S]*?\$\$?', part or ''):
                            flush()
                            pieces.append({'markdown': part, 'display': part})
                        else:
                            runs.append((part, secret))
            if item.tag in self.BLOCKS or item.tag in {'li', 'tr'}:
                runs.append(('\n', False))

        visit(node, encrypted)
        flush()
        return pieces

    def recognized_text(self, pieces):
        return clean(''.join(piece['markdown'] if 'markdown' in piece else
                             md_escape(piece['result']) if piece['encrypted'] else piece['original']
                             for piece in pieces))


def _extract(source: Path, output: Path, resolver, progress=None):
    update_progress(progress, 'read', f'正在读取 {source.name}…')
    archive = Archive(source)
    questions_before = resolver.question_count
    frames = []
    update_progress(progress, 'scan', '正在查找题目和内嵌作业页面…')
    # Scan all HTML MIME parts, including nested iframe content.
    for part in archive.parts:
        if part.get_content_type() != 'text/html':
            continue
        html = decode_text(part)
        if not re.search(r'\b(?:singleQuesId|TiMu)\b', html):
            continue
        root = DOMParser(html).root
        questions = [n for n in root.walk() if n.has_class('singleQuesId')]
        if not questions:
            questions = [n for n in root.walk() if n.has_class('TiMu')]
        if questions:
            frames.append((part, root, questions))
    if not frames:
        raise ValueError('没有找到题目。请在作业题目已加载后重新保存 MHTML；目前适配超星作业页面。')
    total = sum(len(nodes) for _, _, nodes in frames)
    processed = 0
    update_progress(progress, 'questions', f'已找到 {total} 题，准备提取…', 0, total)
    renderer = Renderer(archive, output)
    assignments = []
    seen = set()
    for part, root, nodes in frames:
        base = str(part.get('Content-Location', ''))
        update_progress(progress, 'questions', '正在加载当前作业的字体和图片资源…', processed, total)
        blob = page_font(root, archive, base)
        with TTFont(io.BytesIO(blob)) if blob is not None else nullcontext() as font:
            supported = set(font.getBestCmap()) if font is not None else set()
        headings = [n for n in root.walk() if n.tag in {'h1', 'h2', 'h3'}
                    and (not n.attrs.get('class') or n.has_class('mark_title')) and clean(n.text())]
        title = clean(headings[0].text()) if headings else f'作业 {len(assignments)+1}'
        assignment = {'title': title, 'questions': []}
        for position, node in enumerate(nodes, 1):
            processed += 1
            update_progress(progress, 'questions', f'正在提取第 {processed}/{total} 题…',
                            processed-1, total)
            qid = node.attrs.get('data') or node.attrs.get('id', '')
            modern_title = node.find_class('mark_name') if node.has_class('questionLi') else None
            title_node = modern_title or node.find_class('Zy_TItle')
            if title_node is None:
                renderer.warnings.append(f'{title} 第 {position} 题：未找到题干容器，已跳过')
                update_progress(progress, 'questions', f'已跳过第 {processed} 题：缺少题干容器',
                                processed, total)
                continue
            if modern_title is not None:
                number_match = re.search(r'\d+', node.attrs.get('aria-label', ''))
                number = number_match.group() if number_match else str(position)
                qtype = node.attrs.get('typename', '').strip() or '题目'
                displayed_type = qtype
                blank_count = 0
                # The new editor puts the number and points in the same h3 as
                # the actual stem. Keep only content after the points span.
                content = []
                after_points = False
                for child in modern_title.children:
                    if isinstance(child, Node) and child.has_class('colorShallow'):
                        after_points = True
                    elif after_points:
                        content.append(child)
                stem_node = Node('div', children=content or [child for child in modern_title.children
                                                            if isinstance(child, Node) and child.tag == 'p'])
            else:
                number_node = next((n for n in title_node.walk() if n.tag == 'i'), None)
                number = clean(number_node.text()) if number_node else str(position)
                type_node = title_node.find_class('newZy_TItle')
                qtype = clean(type_node.text()).strip('【】') if type_node else '题目'
                displayed_type = qtype
                blank_items = [n for n in node.walk() if n.has_class('blankItemDiv')]
                blank_count = len(blank_items)
                if blank_count:
                    qtype = '填空题'
                stem_node = title_node.find_class('fontLabel')
                if stem_node is None:
                    stem_node = title_node
            renderer.context = f'{title} 第 {number} 题'
            if displayed_type != qtype:
                renderer.warnings.append(f'{renderer.context}：页面标为{displayed_type}，'
                                         f'但有 {blank_count} 个填空输入框，按填空题导出')
            option_nodes = []
            option_list = node.find_class('Zy_ulTop')
            if modern_title is not None:
                for choice in (n for n in node.walk() if n.has_class('answerBg')):
                    label = choice.find_class('num_option')
                    body = choice.find_class('answer_p')
                    if label is not None and body is not None:
                        option_nodes.append((clean(label.text()), body, False))
            elif option_list:
                for li in (n for n in option_list.walk() if n.tag == 'li'):
                    label = next((n for n in li.walk() if n.has_class('num_option')
                                  or n.has_class('num_option_dx')), None)
                    body = li.find_class('after')
                    if label is not None and body is not None:
                        # Visible labels follow the shuffled display order. data/ARIA
                        # contain the original option IDs and must not be used as labels.
                        option_nodes.append((clean(label.text()), body, li.has_class('font-cxsecret')))
            groups = [renderer.ocr_pieces(stem_node, base, '题干：')]
            groups.extend(renderer.ocr_pieces(body, base, f'选项{label}：', secret)
                          for label, body, secret in option_nodes)
            pieces = [piece for group in groups for piece in group]
            for piece in pieces:
                if blob is not None and 'runs' in piece:
                    piece['encrypted'] = any(secret and ord(char) in supported
                                             for text, secret in piece['runs'] for char in text)
            needs_ocr = any(piece.get('encrypted') for piece in pieces)
            ocr_image = None
            if needs_ocr:
                if blob is None:
                    raise ValueError(f'{renderer.context}：加密字体未保存在 MHTML 中。')
                try:
                    ocr_image = f'ocr_images/question_{len(seen)+1:03d}.png'
                    update_progress(progress, 'questions',
                                    f'正在渲染并使用 {resolver.model} 识别第 {processed}/{total} 题…',
                                    processed-1, total)
                    resolver.recognize(blob, pieces, output / ocr_image)
                except ValueError as exc:
                    raise ValueError(f'{renderer.context}：{exc}') from exc
                stem = renderer.recognized_text(groups[0])
                options = [{'label': entry[0], 'text': renderer.recognized_text(group)}
                           for entry, group in zip(option_nodes, groups[1:])]
            else:
                stem = clean(renderer.render(stem_node, base))
                options = [{'label': label, 'text': clean(renderer.render(body, base))}
                           for label, body, _ in option_nodes]
            if re.search(r'如图|图[\d-]+所示|图中|图所示', stem) and not any(n.tag == 'img' for n in node.walk()):
                renderer.warnings.append(f'{renderer.context}：题干提到图，但保存的题目中没有图片标签，请核对原题')
            key = (title, qid, stem, json.dumps(options, ensure_ascii=False))
            if key in seen:
                update_progress(progress, 'questions', f'已处理第 {processed}/{total} 题（重复题目）',
                                processed, total)
                continue
            seen.add(key)
            question = {'id': qid, 'number': number, 'type': qtype,
                        'stem': stem, 'options': options}
            if ocr_image:
                question['ocr_image'] = ocr_image
            if blank_count:
                question['blank_count'] = blank_count
            if displayed_type != qtype:
                question['displayed_type'] = displayed_type
            assignment['questions'].append(question)
            update_progress(progress, 'questions', f'已处理 {processed}/{total} 题', processed, total)
        if assignment['questions']:
            assignments.append(assignment)
    count = sum(len(a['questions']) for a in assignments)
    if not count:
        raise ValueError('找到题目容器，但未能提取题干。')
    update_progress(progress, 'write', f'正在保存 {count} 题的 Markdown 和题目数据…')
    output.mkdir(parents=True, exist_ok=True)
    lines = ['# 课后作业复习题', '', f'来源文件：{md_escape(source.name)}', '',
             f'共 {len(assignments)} 份作业，{count} 道题。', '',
             '> 题目按保存页面中的顺序导出；图片使用相对路径，请保留 images 文件夹。', '']
    for i, assignment in enumerate(assignments, 1):
        lines.extend([f'## 作业 {i}：{md_escape(assignment["title"])}', '',
                      f'共 {len(assignment["questions"])} 题。', ''])
        for question in assignment['questions']:
            lines.extend([f'### 第 {question["number"]} 题 · {question["type"]}', '',
                          question['stem'], ''])
            if question.get('blank_count'):
                lines.extend([f'填空数量：{question["blank_count"]}。', ''])
            for option in question['options']:
                lines.extend([f'- **{option["label"]}.** ' + option['text'].replace('\n', '\n  '), ''])
    if renderer.warnings:
        lines.extend(['## 导出提示', ''])
        lines.extend('- ' + w for w in dict.fromkeys(renderer.warnings))
        lines.append('')
    (output / 'questions.md').write_text('\n'.join(lines), encoding='utf-8')
    report = {'source_file': source.name, 'assignment_count': len(assignments),
              'question_count': count, 'image_count': len(renderer.images),
              'ocr': {'model': resolver.model,
                      'question_images': resolver.question_count-questions_before,
                      'image_folder': 'ocr_images'},
              'warnings': list(dict.fromkeys(renderer.warnings)), 'assignments': assignments}
    (output / 'questions.json').write_text(json.dumps(report, ensure_ascii=False, indent=2)+'\n',
                                         encoding='utf-8')
    return report


def extract(source: Path, output: Path, resolver=None, render_every=None, image_renderer=None,
            render_width=1280, progress=None):
    if output.exists():
        raise ValueError(f'输出目录已存在：{output}。请指定新的目录，防止覆盖已有笔记。')
    if resolver is None:
        with QuestionOCR() as owned:
            return extract(source, output, owned, render_every, image_renderer, render_width, progress)
    output.parent.mkdir(parents=True, exist_ok=True)
    # Create staging directly beside the destination with ordinary inherited
    # permissions. TemporaryDirectory uses mode 0o700, which restricts Windows
    # ACLs; moving its contents would preserve that restriction in the export.
    staging = output.parent / ('.extract-' + uuid.uuid4().hex)
    staging.mkdir()
    try:
        report = _extract(source, staging, resolver, progress)
        if render_every is not None:
            from render_homework import render
            render(staging, n=render_every, width=render_width, renderer=image_renderer, progress=progress)
        staging.rename(output)
        update_progress(progress, 'saved', f'Markdown 已保存，共 {report["question_count"]} 题',
                        report['question_count'], report['question_count'])
    finally:
        if staging.exists():
            shutil.rmtree(staging)
    return report


def main():
    parser = argparse.ArgumentParser(description='离线提取超星 MHTML 中的作业题目及本地图片。')
    parser.add_argument('sources', nargs='+', type=Path, help='一个或多个 .mhtml/.mht 文件或文件夹')
    parser.add_argument('-o', '--output', type=Path, default=Path('exports'), help='输出根目录（默认 exports）')
    parser.add_argument('--ocr-model', choices=('v4', 'v6tiny'), default='v4',
                        help='本地 OCR 模型（默认 v4；可选 v6tiny）')
    parser.add_argument('--progress-json', action='store_true', help='实时输出供界面读取的进度事件')
    parser.add_argument('--render-every', type=int, metavar='N', help='导出时每 N 题渲染为一张 PNG')
    parser.add_argument('--render-width', type=int, default=1280, help='渲染图片宽度（默认 1280 像素）')
    args = parser.parse_args()
    if args.render_every is not None and (args.render_every < 1 or args.render_width < 480):
        parser.error('渲染题数必须大于 0，图片宽度不能小于 480 像素。')
    sources = []
    for path in args.sources:
        if path.is_dir():
            sources.extend(sorted(p for p in path.iterdir() if p.suffix.lower() in {'.mhtml', '.mht'}))
        else:
            sources.append(path)
    sources = list(dict.fromkeys(p.resolve() for p in sources))
    if not sources:
        parser.error('没有找到 .mhtml/.mht 文件。')
    failures = 0
    progress = print_progress if args.progress_json else None
    from contextlib import ExitStack
    with ExitStack() as stack:
        resolver = stack.enter_context(QuestionOCR(model=args.ocr_model))
        image_renderer = None
        if args.render_every is not None:
            from render_homework import BrowserRenderer
            try:
                image_renderer = stack.enter_context(BrowserRenderer(args.render_width, progress=progress))
            except OSError as exc:
                print(f'启动图片渲染失败：{exc}', file=sys.stderr)
                return 1
        for source in sources:
            try:
                result = extract(source, args.output / source.stem, resolver, args.render_every,
                                 image_renderer, args.render_width, progress)
                print(f'{source.name}：{result["assignment_count"]} 份作业，'
                      f'{result["question_count"]} 题，{result["image_count"]} 张图片')
                print(f'  Markdown：{args.output / source.stem / "questions.md"}')
                if args.render_every is not None:
                    image_count = (result['question_count']+args.render_every-1)//args.render_every
                    print(f'  渲染图片：{image_count} 张，{args.output / source.stem / "rendered"}')
                print(f'  OCR：{result["ocr"]["model"]} 识别 '
                      f'{result["ocr"]["question_images"]} 张整题文字图，'
                      '不使用字体映射或识别缓存')
                for warning in result['warnings']:
                    print('  提示：' + warning)
            except (OSError, ValueError, TTLibError) as exc:
                failures += 1
                print(f'{source.name}：导出失败：{exc}', file=sys.stderr)
    return 1 if failures else 0


if __name__ == '__main__':
    raise SystemExit(main())
